<?php
require dirname(__DIR__).'/bootstrap.php';
use App\Core\Auth;use App\Services\RestaurantService;
Auth::requireLogin();if(!Auth::canAccess('reports')){http_response_code(403);exit('Forbidden');}$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$d=(new RestaurantService())->reports($from,$to);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="kedai-bara-report-'.$from.'-'.$to.'.csv"');$o=fopen('php://output','w');fwrite($o,"\xEF\xBB\xBF");fputcsv($o,['Kedai Bara Report',$from.' s/d '.$to]);fputcsv($o,['Net Sales',$d['revenue']]);fputcsv($o,['Orders',$d['orders']]);fputcsv($o,['Discounts',$d['discounts']]);fputcsv($o,['Refunds',$d['refunds']]);fputcsv($o,['COGS',$d['cogs']]);fputcsv($o,['Gross Profit',$d['revenue']-$d['cogs']]);fputcsv($o,[]);fputcsv($o,['Daily Sales']);fputcsv($o,['Date','Revenue']);foreach($d['daily'] as $r)fputcsv($o,[$r['d'],$r['revenue']]);fputcsv($o,[]);fputcsv($o,['Top Menu']);fputcsv($o,['Menu','Qty','Sales']);foreach($d['topItems'] as $r)fputcsv($o,[$r['item_name'],$r['qty'],$r['sales']]);fclose($o);exit;
